nodes.text:
Input: 1) {}_H^W \hat{q}, hand quaternion; 2) {}_B^W \hat{q}, robot quaternion; 3) {}_H^H \omega, hand angular velocity; 4) {}_H^W q_{\text{start}}, initial hand quat to start the rotation; 5) T_{\text{rot}}, rotation period; 6) \varepsilon_{\text{entry}}=0.2, \varepsilon_{\text{exit}}=0.1, \theta_{\text{trig}}=0.4, T_{\text{guard}}=5 s, parameters for continuous rotation.
Output: {}_B^W q_c and \omega_c, the target orientation and angular velocity of the aerial robot, respectively.
1: while in Operation Mode do
2:     q_e \leftarrow \text{QUATERROR}({}_H^W \hat{q}, {}_H^W q_{\text{start}});
3:     v_e \leftarrow \text{sign}(q_{e,w}) [q_{e,x}, q_{e,y}, q_{e,z}]^T;
4:     if not ISROTATING() then
5:         if \text{ALIGN}(\mathbf{v}_{e,xy}, \mathbf{0}, \varepsilon_{\text{entry}}) then
6:             if |\mathbf{v}_{e,z}| > \theta_{\text{trig}} then
7:                 t_0 \leftarrow \text{NOW}();
8:                 \psi_0 \leftarrow \text{CONVERTTOYAW}(\mathbf{v}_{e,z});
9:                 d_r \leftarrow \text{sign}(\mathbf{v}_{e,z}) \in \{+1, -1\};
10:         end if
11:     end if
12:     return \{{}_B^W q_c \leftarrow {}_H^W \hat{q}, \omega_c \leftarrow {}_H^H \omega\};
13:     end if
14:     \tau \leftarrow \text{NOW}() - t_0;
15:     q_{e,r2h} \leftarrow \text{QUATERROR}({}_B^W \hat{q}, {}_H^W \hat{q});
16:     \mathbf{v}_{e,r2h} \leftarrow \text{sign}(q_{e,r2h,w}) [q_{e,r2h,x}, q_{e,r2h,y}, q_{e,r2h,z}]^T;
17:     c_1 \leftarrow \text{ALIGN}(\mathbf{v}_{e,r2h}, \mathbf{0}, \varepsilon_{\text{exit}});
18:     c_2 \leftarrow (\tau > T);
19:     if (c_1 \vee c_2) \wedge (\tau > T_{\text{guard}}) then
20:         RESET();
21:         return \{{}_B^W q_c \leftarrow {}_H^W \hat{q}, \omega_c \leftarrow {}_H^H \omega\};
22:     end if
23:     \omega \leftarrow 2\pi/T \cdot d_r;
24:     {}_B^W q_c \leftarrow \text{EULERTOQUAT}(0, \pi/2, \omega\tau + \psi_0);
25:     \omega_c \leftarrow (0, 0, \omega);
26:     return \{{}_B^W q_c, \omega_c\}
27: end while

